// Service worker: precache everything so the app works offline.
// VERSION and ASSETS are regenerated by scripts/sw-manifest.mjs on deploy.
const VERSION = '5763a1bf36';
const ASSETS = [/*ASSETS*/
  './',
  './css/app.css',
  './icons/apple-touch-icon.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon.svg',
  './index.html',
  './js/app.js',
  './js/core/astro.js',
  './js/core/calendars.js',
  './js/core/chart.js',
  './js/core/chinese.js',
  './js/core/marks.js',
  './js/core/numerology.js',
  './js/core/rng.js',
  './js/core/store.js',
  './js/core/ui.js',
  './js/data/astro-text.js',
  './js/data/casting.js',
  './js/data/cities.js',
  './js/data/energy.js',
  './js/data/lexicon.js',
  './js/data/oracle.js',
  './js/data/quizzes.js',
  './js/data/symbols.js',
  './js/data/tarot.js',
  './js/registry.js',
  './js/tools/astrology.js',
  './js/tools/body.js',
  './js/tools/cards.js',
  './js/tools/casting.js',
  './js/tools/cycles.js',
  './js/tools/eastern.js',
  './js/tools/energy.js',
  './js/tools/inner.js',
  './js/tools/nature.js',
  './js/tools/numerology.js',
  './js/tools/self.js',
  './js/tools/signs.js',
  './js/views/compass.js',
  './js/views/journal.js',
  './js/views/profile.js',
  './js/views/today.js',
  './manifest.webmanifest'
];
const CACHE = 'soul-compass-' + VERSION;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('soul-compass-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).then((r) => { const copy = r.clone(); caches.open(CACHE).then((c) => c.put('./index.html', copy)); return r; }).catch(() => caches.match('./index.html')));
    return;
  }
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((r) => {
    if (r.ok) { const copy = r.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return r;
  })));
});
